-- Reuse genuine, already-published facts during incremental bootstrap. No original source, token or price is fabricated.
CREATE FUNCTION observability.published_runtime_fold(m jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_build_object(
 'tokens',jsonb_build_object('input',coalesce(m#>>'{tokens,input}',m#>>'{recordedUsage,tokens,input}','0'),'cacheRead',coalesce(m#>>'{tokens,cacheRead}',m#>>'{recordedUsage,tokens,cacheRead}','0'),'cacheWrite',coalesce(m#>>'{tokens,cacheWrite}',m#>>'{recordedUsage,tokens,cacheWrite}','0'),'output',coalesce(m#>>'{tokens,output}',m#>>'{recordedUsage,tokens,output}','0')),
 'bucketRecords',CASE WHEN m->>'state'='ready' THEN jsonb_build_object('input',m->>'records','cacheRead',m->>'records','cacheWrite',m->>'records','output',m->>'records') ELSE coalesce(m#>'{recordedUsage,bucketRecords}','{"input":"0","cacheRead":"0","cacheWrite":"0","output":"0"}'::jsonb) END,
 'executions',coalesce(m->>'executions',m#>>'{recordedUsage,executions}','0'),'observedExecutions',coalesce(m->>'observedExecutions',m#>>'{recordedUsage,observedExecutions}','0'),'records',coalesce(m->>'records',m#>>'{recordedUsage,records}',m#>>'{costCoverage,records}','0'),
 'pricedRecords',CASE WHEN m#>>'{cost,state}'='complete' THEN m->>'records' ELSE coalesce(m#>>'{recordedCost,pricedRecords}','0') END,'partiallyPricedRecords',coalesce(m#>>'{recordedCost,partiallyPricedRecords}','0'),
 'picos',trim_scale(coalesce(m#>>'{cost,amount}',m#>>'{recordedCost,amount}','0')::numeric*1000000000000)::text,
 'visible',coalesce(m#>>'{cost,state}','')<>'hidden' AND coalesce(m#>>'{costCoverage,visibility}','')<>'hidden','priced',coalesce(m#>>'{cost,state}'='complete' OR m->>'state'='not-applicable',false),'gaps',coalesce(m->'gaps','[]'::jsonb)) $$;
CREATE TEMP TABLE published_runtime_seed AS
 SELECT DISTINCT ON(r.key) r.key AS task_id,r.report_id AS source_report,r.document AS summary,coalesce(p.report->'header',p.report#>'{facts,header}') AS header
 FROM observability.runtime_report_rows r JOIN observability.runtime_reports p ON p.id=r.report_id
 WHERE r.section='tasks' AND r.parent='' AND p.state IN('ready','not-ready') AND r.document->>'id'=r.key
 AND r.document->>'projectId' IS NOT NULL AND r.document->>'protocol' IN('legacy','v3','development') AND r.document->'metrics'->>'state' IN('ready','not-ready','not-applicable')
 ORDER BY r.key,coalesce(p.report#>>'{header,asOf}',p.report#>>'{facts,header,asOf}') DESC,
 CASE WHEN r.document#>>'{metrics,cost,state}'='complete' OR r.document#>>'{metrics,recordedCost,amount}' IS NOT NULL THEN 0 ELSE 1 END;
INSERT INTO observability.runtime_task_metadata(task_id,project_id,source_kind,created_at,document)
 SELECT task_id,summary->>'projectId',coalesce(summary#>>'{source,kind}','business-task'),(summary->>'createdAt')::timestamptz,summary-ARRAY['attemptCount','metrics','timing','phaseTiming','projection'] FROM published_runtime_seed ON CONFLICT DO NOTHING;
INSERT INTO observability.runtime_task_cache(task_id,project_id,source_kind,created_at,source_revision,version,document)
 SELECT task_id,summary->>'projectId',coalesce(summary#>>'{source,kind}','business-task'),(summary->>'createdAt')::timestamptz,header->>'sourceRevision','published-seed:'||source_report||':'||task_id,
 jsonb_build_object('task',summary-ARRAY['attemptCount','metrics','timing','phaseTiming','projection'],'fold',observability.published_runtime_fold(summary->'metrics'),'build',jsonb_build_object('attemptCount',summary->>'attemptCount','timing',summary->'timing','phaseTiming',summary->'phaseTiming','sourceReceipts','[]'::jsonb,'persistedThrough','0'),'sourceRevision',header->>'sourceRevision','capturedAt',header->>'asOf','version','published-seed:'||source_report||':'||task_id)
 FROM published_runtime_seed ON CONFLICT DO NOTHING;
INSERT INTO observability.runtime_task_cache_rows(task_id,version,role,key,document)
 SELECT s.task_id,'published-seed:'||s.source_report||':'||s.task_id,'public-rows',lpad(r.ordinal::text,30,'0'),jsonb_build_object('section',r.section,'parent',nullif(r.parent,''),'key',r.key,'document',r.document)
 FROM published_runtime_seed s JOIN observability.runtime_report_rows r ON r.report_id=s.source_report AND r.parent=s.task_id AND r.section IN('attempts','calls','swimlane','phases','fragments') ON CONFLICT DO NOTHING;
INSERT INTO observability.runtime_task_cache_rows(task_id,version,role,key,document)
 SELECT s.task_id,'published-seed:'||s.source_report||':'||s.task_id,'public-counts',c.section||':'||c.parent,jsonb_build_object('section',c.section,'parent',nullif(c.parent,''),'total',c.total::text)
 FROM published_runtime_seed s JOIN observability.runtime_report_counts c ON c.report_id=s.source_report AND c.parent=s.task_id ON CONFLICT DO NOTHING;
INSERT INTO observability.runtime_task_work(key,project_id,requires_full) SELECT task_id,summary->>'projectId',true FROM published_runtime_seed ON CONFLICT DO NOTHING;
CREATE TEMP TABLE published_runtime_seed_daily AS SELECT c.*,"scope"."value" AS scope,(c.created_at AT TIME ZONE 'UTC')::date AS day FROM observability.runtime_task_cache c CROSS JOIN LATERAL(VALUES(''),(c.project_id))scope(value) WHERE c.version LIKE 'published-seed:%';
INSERT INTO observability.runtime_daily_aggregates(scope,day,source_kind,tasks,input,cache_read,cache_write,output,input_records,cache_read_records,cache_write_records,output_records,executions,observed,records,priced_records,partial_records,picos,unpriced_tasks,gaps)
 SELECT scope,day,source_kind,count(*),sum((document#>>'{fold,tokens,input}')::numeric),sum((document#>>'{fold,tokens,cacheRead}')::numeric),sum((document#>>'{fold,tokens,cacheWrite}')::numeric),sum((document#>>'{fold,tokens,output}')::numeric),sum((document#>>'{fold,bucketRecords,input}')::numeric),sum((document#>>'{fold,bucketRecords,cacheRead}')::numeric),sum((document#>>'{fold,bucketRecords,cacheWrite}')::numeric),sum((document#>>'{fold,bucketRecords,output}')::numeric),sum((document#>>'{fold,executions}')::numeric),sum((document#>>'{fold,observedExecutions}')::numeric),sum((document#>>'{fold,records}')::numeric),sum((document#>>'{fold,pricedRecords}')::numeric),sum((document#>>'{fold,partiallyPricedRecords}')::numeric),sum((document#>>'{fold,picos}')::numeric),count(*) FILTER(WHERE document#>>'{fold,priced}'='false'),
 coalesce((SELECT jsonb_object_agg("g"."reason","g"."n"::text) FROM(SELECT reason,count(*) AS n FROM published_runtime_seed_daily d CROSS JOIN LATERAL jsonb_array_elements_text(d.document#>'{fold,gaps}')reason WHERE d.scope=p.scope AND d.day=p.day AND d.source_kind=p.source_kind GROUP BY reason)g),'{}'::jsonb)
 FROM published_runtime_seed_daily p GROUP BY scope,day,source_kind ON CONFLICT(scope,day,source_kind) DO UPDATE SET tasks=observability.runtime_daily_aggregates.tasks+"excluded"."tasks", input=observability.runtime_daily_aggregates.input+"excluded"."input", cache_read=observability.runtime_daily_aggregates.cache_read+"excluded"."cache_read", cache_write=observability.runtime_daily_aggregates.cache_write+"excluded"."cache_write", output=observability.runtime_daily_aggregates.output+"excluded"."output", input_records=observability.runtime_daily_aggregates.input_records+"excluded"."input_records", cache_read_records=observability.runtime_daily_aggregates.cache_read_records+"excluded"."cache_read_records", cache_write_records=observability.runtime_daily_aggregates.cache_write_records+"excluded"."cache_write_records", output_records=observability.runtime_daily_aggregates.output_records+"excluded"."output_records", executions=observability.runtime_daily_aggregates.executions+"excluded"."executions", observed=observability.runtime_daily_aggregates.observed+"excluded"."observed", records=observability.runtime_daily_aggregates.records+"excluded"."records", priced_records=observability.runtime_daily_aggregates.priced_records+"excluded"."priced_records", partial_records=observability.runtime_daily_aggregates.partial_records+"excluded"."partial_records", picos=observability.runtime_daily_aggregates.picos+"excluded"."picos", unpriced_tasks=observability.runtime_daily_aggregates.unpriced_tasks+"excluded"."unpriced_tasks", gaps=(SELECT coalesce(jsonb_object_agg(reason,n::text),'{}'::jsonb) FROM(SELECT reason,sum(value::numeric) AS n FROM(SELECT key AS reason,value FROM jsonb_each_text(observability.runtime_daily_aggregates.gaps) UNION ALL SELECT key AS reason,value FROM jsonb_each_text("excluded"."gaps"))g GROUP BY reason)x);
UPDATE observability.runtime_projection_head SET revision=greatest(revision,1),as_of=(SELECT max(document->>'capturedAt') FROM observability.runtime_task_cache) WHERE singleton=true AND EXISTS(SELECT 1 FROM published_runtime_seed);
INSERT INTO observability.runtime_projection_scopes(project_id,revision,as_of) SELECT project_id,1,max(document->>'capturedAt') FROM observability.runtime_task_cache GROUP BY project_id ON CONFLICT DO NOTHING;
DROP TABLE published_runtime_seed_daily;
DROP TABLE published_runtime_seed;
